// The wiki's own numbers for the post-1.21.4 content src/futureContent.js registers. That file was generated by
// guessing from names (every item stacking to 64, no tool or armour stats, every block of a family the same
// hardness), so the item and block parity audits failed on it. This layer replaces the guesses with the values in
// src/resourceWikiData.js -- the Module:Default data component/items components and the pages' infoboxes -- when
// blocks.js loads. Nothing here is typed by hand except copper's tier, from the Tiers page's table.
import { WIKI_ITEMS, WIKI_BLOCKS } from './resourceWikiData.js';
import { FIXED_DURABILITY } from './durability.js';

/** Tiers page: "Copper | 1 | 191 | 5 | 1 | 13 (8 on armor)" -- mining level 1 (as stone), mining efficiency 5. */
export const COPPER_TIER = Object.freeze({ miningLevel: 1, speed: 5 });

const ARMOUR_SLOTS = { head: 'head', chest: 'chest', legs: 'legs', feet: 'feet' };
const TOOL = /_(pickaxe|axe|shovel|hoe|sword|spear)$/;

/** Apply the wiki's item components to each future item: stack, durability, attack, armour, enchantability. */
export function applyWikiItemStats(items, futureItems) {
  const changed = [];
  for (const id of Object.keys(futureItems)) {
    const wiki = WIKI_ITEMS[id];
    const def = items[id];
    if (!wiki || !def) continue;
    const before = JSON.stringify(def);
    if (wiki.stack !== undefined) def.stackSize = wiki.stack;
    if (wiki.durability !== undefined) FIXED_DURABILITY[id] = wiki.durability;
    if (wiki.attack !== undefined) def.attack = wiki.attack;
    if (wiki.attackSpeed !== undefined) def.attackSpeed = wiki.attackSpeed;
    if (wiki.enchantability !== undefined) def.enchantability = wiki.enchantability;
    if (wiki.armor !== undefined) {
      def.armor = wiki.armor;
      def.toughness = wiki.toughness ?? 0;
      if (wiki.knockbackResistance !== undefined) def.knockbackResistance = wiki.knockbackResistance;
      // A player's armour piece has a slot; horse and nautilus armour ("body") are worn by the animal.
      if (ARMOUR_SLOTS[wiki.slot]) { def.armorSlot = ARMOUR_SLOTS[wiki.slot]; def.type = 'armor'; }
    }
    if (TOOL.test(id)) {
      def.type = /_(sword|spear)$/.test(id) ? 'weapon' : 'tool';
      if (id.startsWith('copper_') && !/_(sword|spear)$/.test(id)) def.speed = COPPER_TIER.speed;
    }
    if (JSON.stringify(def) !== before) changed.push(id);
  }
  return changed;
}

/**
 * Apply the wiki's block facts (hardness, blast resistance, light) to each future block, keyed by its name as
 * WIKI_BLOCKS is. A block the wiki data does not cover keeps its definition.
 */
export function applyWikiBlockStats(blockDefs, futureBlockDefs) {
  const changed = [];
  for (const key of Object.keys(futureBlockDefs)) {
    const def = blockDefs[key];
    const wiki = def && WIKI_BLOCKS[def.name];
    if (!wiki) continue;
    const before = JSON.stringify(def);
    if (typeof wiki.hardness === 'number') def.hardness = wiki.hardness;
    if (typeof wiki.blast === 'number') def.resistance = wiki.blast;
    if (typeof wiki.light === 'number') { if (wiki.light > 0) def.light = wiki.light; else delete def.light; }
    if (JSON.stringify(def) !== before) changed.push(def.name);
  }
  return changed;
}

const keyOf = (name) => String(name ?? '').toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_|_$/g, '');

/**
 * Harvest rows (blockHarvestData.js's shape) for the future blocks, from each block's wiki {{breaking row}}:
 * hardness, proper tool, the tier it needs to drop anything, and blast resistance. Without these the blocks fell
 * back to a guessed sibling's row (a shelf took a plank's, copper bars a copper block's "needs stone").
 */
export function futureHarvestRows(futureBlockDefs) {
  const rows = {};
  for (const def of Object.values(futureBlockDefs)) {
    const wiki = WIKI_BLOCKS[def?.name];
    if (!wiki || typeof wiki.hardness !== 'number') continue;
    const b = wiki.breaking ?? {};
    const row = { hardness: wiki.hardness, drops: b.selfDrop === false ? [] : [keyOf(def.name)] };
    if (b.tool && b.tool !== 'any') row.tool = b.tool;
    if (b.tier) { row.tier = b.tier; row.requiresTool = true; }
    if (typeof wiki.blast === 'number') row.resistance = wiki.blast;
    rows[keyOf(def.name)] = row;
  }
  return rows;
}

/** The future blocks' drop rules from their breaking rows: shears collect it, Silk Touch collects it, it never drops itself. */
export function futureDropRules(futureBlockDefs) {
  const shears = new Set(); const silk = new Set(); const noSelf = new Set();
  for (const def of Object.values(futureBlockDefs)) {
    const b = WIKI_BLOCKS[def?.name]?.breaking;
    if (!b) continue;
    const key = keyOf(def.name);
    if (b.shears) shears.add(key);
    if (b.silk) silk.add(key);
    if (b.selfDrop === false) noSelf.add(key);
  }
  return { shears, silk, noSelf };
}

// Shapes. The wiki marks these "transparent: yes" (light passes; they are not full cubes), and the generated
// definitions drew them as cubes. Each copper variant takes the shape of the vanilla block it is the copper form
// of; the shelf and the golem statue have no vanilla twin, so they get box models traced from the wiki's renders
// (approximations: the pages give the look, not pixel coordinates).
const SHAPE_TWINS = [
  [/Copper Bars$/, 'Iron Bars', ['pane']],
  [/Copper Chain$/, 'Chain', ['chain']],
  [/Copper Lantern$/, 'Lantern', ['model']],
  [/^Potted /, 'Potted Dandelion', ['flowerPot']],
];
const TRACED_MODELS = [
  // A shelf: a back board, a floor and a roof, open at the front.
  [/ Shelf$/, { boxes: [[0, 0, 13, 16, 16, 16], [0, 0, 0, 16, 2, 16], [0, 14, 0, 16, 16, 16]] }],
  // A copper golem statue: legs, body and the big head of the golem.
  [/Copper Golem Statue$/, { boxes: [[5, 0, 6, 11, 4, 10], [4, 4, 5, 12, 9, 11], [3, 9, 3, 13, 16, 13]] }],
];

export function applyVanillaShapes(blockDefs, futureBlockDefs) {
  const byName = new Map(Object.values(blockDefs).filter(Boolean).map((d) => [d.name, d]));
  const changed = [];
  for (const key of Object.keys(futureBlockDefs)) {
    const def = blockDefs[key];
    if (!def?.name) continue;
    for (const [pattern, twinName, fields] of SHAPE_TWINS) {
      const twin = byName.get(twinName);
      if (!pattern.test(def.name) || !twin) continue;
      for (const f of fields) if (twin[f] !== undefined) def[f] = twin[f];
      def.transparent = true;
      changed.push(def.name);
    }
    for (const [pattern, model] of TRACED_MODELS) {
      if (!pattern.test(def.name)) continue;
      def.model = model; def.transparent = true;
      changed.push(def.name);
    }
  }
  return changed;
}

/**
 * The generated definitions' flags in this game's vocabulary. Sounds: the game has grass, gravel, stone, sand,
 * wood, water, snow, glass, wool and metal; the generator wrote "cloth" (wool's sound group) and "copper". A plant
 * is transparent and not solid, like every sapling the game already has. A block the wiki calls "Sulfur Block"
 * does not exist: the game's old block 139 of that name now drops the wiki's Sulfur and takes its stats.
 */
const SOUND_NAMES = { cloth: 'wool', copper: 'metal' };
export function normaliseFutureFlags(blockDefs, futureBlockDefs, blocks) {
  for (const key of Object.keys(futureBlockDefs)) {
    const def = blockDefs[key];
    if (!def) continue;
    if (SOUND_NAMES[def.sound]) def.sound = SOUND_NAMES[def.sound];
    if (def.plant) { def.transparent = true; def.solid = false; }
  }
  const legacy = blockDefs[blocks.SULFUR_BLOCK]; const sulfur = blockDefs[blocks.SULFUR];
  if (legacy && sulfur) Object.assign(legacy, { drop: blocks.SULFUR, hardness: sulfur.hardness, resistance: sulfur.resistance });
}

/**
 * The generated Poplar Door had no open, top or top-open block, and the Poplar Trapdoor was marked a door (the
 * generator tested "door" before "trapdoor"). Every door here is four blocks and every trapdoor two, so the future
 * ones get their states the way the wood doors in extraContent.js have them, with new ids above the highest.
 */
export function addFutureDoorStates(blocks, blockDefs, futureBlockIds) {
  let next = Math.max(...Object.keys(blockDefs).map(Number)) + 1;
  const added = [];
  const make = (key, def) => { blocks[key] = next; blockDefs[next] = def; added.push(key); return next++; };
  for (const key of Object.keys(futureBlockIds)) {
    const id = blocks[key]; const def = blockDefs[id];
    if (!def) continue;
    const base = { hardness: def.hardness, sound: def.sound, resistance: def.resistance, isIron: false, transparent: true, drop: id };
    if (/_TRAPDOOR$/.test(key)) {
      const tex = { all: def.name === 'Poplar Trapdoor' ? 'poplar_trapdoor.png' : def.textures?.all };
      delete def.door;
      Object.assign(def, { trapdoor: true, isIron: false, isTop: false, transparent: true, textures: tex });
      if (blocks[`${key}_OPEN`] === undefined) def.openId = make(`${key}_OPEN`, { ...base, name: `${def.name} Open`, trapdoor: true, isTop: false, solid: false, internal: true, textures: tex });
    } else if (/_DOOR$/.test(key) && def.door) {
      const wood = key.slice(0, -'_DOOR'.length).toLowerCase();
      const tex = { bottom: `${wood}_door_bottom.png`, top: `${wood}_door_top.png`, all: `${wood}_door_bottom.png` };
      Object.assign(def, { isIron: false, isTop: false, transparent: true, textures: tex });
      if (blocks[`${key}_OPEN`] !== undefined) continue;
      def.openId = make(`${key}_OPEN`, { ...base, name: `${def.name} Open`, door: true, isTop: false, solid: false, internal: true, textures: tex });
      make(`${key}_TOP`, { ...base, name: `${def.name} Top`, door: true, isTop: true, internal: true, textures: tex });
      make(`${key}_TOP_OPEN`, { ...base, name: `${def.name} Top Open`, door: true, isTop: true, solid: false, internal: true, textures: tex });
    }
  }
  return added;
}
